"""Generate dense, instruction-pattern-rich test inputs for each BCJ filter."""
import random, struct

def rand_words(rng, n, choices):
    """n 32-bit words drawn from pattern choices (call-able opcodes biased)."""
    out = bytearray()
    for _ in range(n):
        out += struct.pack("<I", rng.choice(choices)())
    return bytes(out)

def gen_x86(rng, size):
    # bytes biased to 0xE8/0xE9 with following bytes 0x00/0xFF heavy
    pool = [0xE8]*8 + [0xE9]*8 + [0x00]*12 + [0xFF]*12 + [0x01, 0x02, 0x10, 0x7F, 0x80, 0xFE, 0xE7, 0xEA]
    return bytes(rng.choice(pool) for _ in range(size))

def gen_powerpc(rng, size):
    n = size // 4
    def w():
        r = rng.random()
        if r < 0.45:
            return 0x48000001 | (rng.getrandbits(24) & 0x03FFFFFC)
        if r < 0.6:
            return 0x48000001 | rng.getrandbits(32) & 0x03FFFFF | 0  # arbitrary low bits
        if r < 0.7:
            return 0x48000000 | rng.getrandbits(24)   # wrong LK/AA
        return rng.getrandbits(32)
    out = bytearray()
    for _ in range(n):
        out += struct.pack(">I", w())
    out += bytes(rng.getrandbits(8) for _ in range(size - n*4))
    return bytes(out)

def gen_arm(rng, size):
    n = size // 4
    def w():
        r = rng.random()
        if r < 0.5:
            return 0xEB000000 | rng.getrandbits(24)
        if r < 0.6:
            return 0xEA000000 | rng.getrandbits(24)   # B not BL
        return rng.getrandbits(32)
    out = bytearray()
    for _ in range(n):
        out += struct.pack("<I", w())
    out += bytes(rng.getrandbits(8) for _ in range(size - n*4))
    return bytes(out)

def gen_armthumb(rng, size):
    n = size // 2
    out = bytearray()
    i = 0
    while i < n:
        if rng.random() < 0.4 and i + 1 < n:
            # BL pair: F0xx F8xx (also test F1..F7 / F9..FF variants sometimes)
            hi1 = 0xF0 | (rng.getrandbits(3) if rng.random() < 0.8 else rng.getrandbits(3) | 0x8)
            lo1 = rng.getrandbits(8)
            hi2 = 0xF8 | (rng.getrandbits(3) if rng.random() < 0.8 else rng.getrandbits(3) | 0x8)
            lo2 = rng.getrandbits(8)
            out += bytes([lo1, hi1, lo2, hi2])
            i += 2
        else:
            out += struct.pack("<H", rng.getrandbits(16))
            i += 1
    return bytes(out[:size])

def gen_sparc(rng, size):
    n = size // 4
    def w():
        r = rng.random()
        if r < 0.3:
            return 0x40000000 | rng.getrandbits(22)          # positive call
        if r < 0.5:
            return 0x7FFFFFC0 | rng.getrandbits(22) | 0x3FC00000 & 0 # negative-ish
        if r < 0.55:
            return 0x7FC00000 | rng.getrandbits(22)
        if r < 0.6:
            return 0x40400000 | rng.getrandbits(22)  # bad byte1 pattern
        return rng.getrandbits(32)
    out = bytearray()
    for _ in range(n):
        out += struct.pack(">I", w())
    out += bytes(rng.getrandbits(8) for _ in range(size - n*4))
    return bytes(out)

def gen_arm64(rng, size):
    n = size // 4
    def w():
        r = rng.random()
        if r < 0.45:
            return 0x94000000 | rng.getrandbits(26)
        if r < 0.55:
            return 0x97000000 | rng.getrandbits(26)   # 0x94|0x03 high bits
        if r < 0.62:
            return 0x14000000 | rng.getrandbits(26)   # B not BL
        return rng.getrandbits(32)
    out = bytearray()
    for _ in range(n):
        out += struct.pack("<I", w())
    out += bytes(rng.getrandbits(8) for _ in range(size - n*4))
    return bytes(out)

def gen_riscv(rng, size):
    n = size // 2
    out = bytearray()
    i = 0
    while i < n:
        r = rng.random()
        if r < 0.25 and i + 1 < n:
            # JAL with random imm and rd
            imm = rng.getrandbits(21)
            inst = ((imm & 0x100000) << 11) | ((imm & 0x7FE) << 20) \
                   | ((imm & 0x800) << 9) | (imm & 0xFF000) \
                   | (rng.getrandbits(5) << 7) | 0x6F
            out += struct.pack("<I", inst)
            i += 2
        elif r < 0.5 and i + 3 < n:
            # AUIPC + JALR (matching rs sometimes)
            rd = rng.getrandbits(5)
            auipc = (rng.getrandbits(20) << 12) | (rd << 7) | 0x17
            rs1 = rd if rng.random() < 0.7 else rng.getrandbits(5)
            jalr = (rng.getrandbits(12) << 20) | (rs1 << 15) \
                   | (rng.getrandbits(3) << 12 if rng.random() < 0.3 else 0) \
                   | (rng.getrandbits(5) << 7) | 0x67
            out += struct.pack("<I", auipc) + struct.pack("<I", jalr)
            i += 4
        else:
            out += struct.pack("<H", rng.getrandbits(16))
            i += 1
    return bytes(out[:size])

def gen_ia64(rng, size):
    # build 16-byte bundles with branch-heavy templates
    out = bytearray()
    while len(out) + 16 <= size:
        tmpl = rng.choice([0x10, 0x11, 0x12, 0x13, 0x16, 0x17, 0x18, 0x19,
                           0x1C, 0x1D, 0x00, 0x05, 0x1F])
        slots = [rng.getrandbits(41) for _ in range(3)]
        # bias slots to look like br.call: opcode 5 at bits 37-40, bits 13-15 zero
        for s in range(3):
            if rng.random() < 0.55:
                v = slots[s] & ~((0xF << 37) | (0x7 << 13) | (1 << 36))
                v |= 0x5 << 37
                v |= rng.getrandbits(20) << 13   # imm20b, low 3 bits are 0 after mask? no: we cleared 13-15 then set full 20 bits... keep simple: random with opcode 5
                if rng.random() < 0.5:
                    v &= ~(0x7 << 13)
                v |= (rng.getrandbits(1) << 36)
                slots[s] = v & ((1 << 41) - 1)
        # pack bundle: 5-bit template then 3x41-bit slots, little endian
        bits = tmpl
        for s in range(3):
            bits |= slots[s] << (5 + 41 * s)
        out += bits.to_bytes(16, "little")
    out += bytes(rng.getrandbits(8) for _ in range(size - len(out)))
    return bytes(out)

GENERATORS = {
    0x04: ("x86", gen_x86, 1),
    0x05: ("powerpc", gen_powerpc, 4),
    0x06: ("ia64", gen_ia64, 16),
    0x07: ("arm", gen_arm, 4),
    0x08: ("armthumb", gen_armthumb, 2),
    0x09: ("sparc", gen_sparc, 4),
    0x0A: ("arm64", gen_arm64, 4),
    0x0B: ("riscv", gen_riscv, 2),
}

