from oracle import ref_decode

def mk(imm24, pad=0, hi=0xEB):
    return b'\x00'*pad + bytes([imm24 & 0xFF, (imm24>>8)&0xFF, (imm24>>16)&0xFF, hi]) + b'\x00'*4

def imm_of(out, pad=0):
    b = out[pad:pad+4]
    return b[0] | (b[1]<<8) | (b[2]<<16)

for src in [0, 1, 2, 0x100, 0xFFFFFF, 0x800000]:
    out = ref_decode(mk(src), filter_id=0x07)
    print(f"src={src:#09x} -> dest={imm_of(out):#09x} (diff={(imm_of(out)-src)&0xFFFFFF:#x})")
for pad in [4, 8]:
    out = ref_decode(mk(0, pad), filter_id=0x07)
    print(f"pad={pad}: dest={imm_of(out, pad):#09x}")
for start in [4, 8, 0x1000]:
    out = ref_decode(mk(0), filter_id=0x07, start=start)
    print(f"start={start:#x}: dest={imm_of(out):#09x}")
# which high bytes trigger?
for hi in [0xEA, 0xEB, 0xEC, 0x0B]:
    out = ref_decode(mk(0, 0, hi), filter_id=0x07)
    print(f"hi={hi:#04x}: dest={imm_of(out):#09x} changed={out[0:4] != mk(0,0,hi)[0:4]}")
EOF

